mapper.select:
select et.*
from Engineering_Training et

    et.state != 3
    
        and et.Et_Company_Name like concat('%',#{params.etCompanyName},'%')
    
    
        and et.Et_Type=#{params.etType}
    
    
        and et.Et_Company_Id=#{params.etCompanyId}
    
    
        and et.Et_Form=#{params.etForm}
    
    order by et.Create_Time desc
